gIi(){return"\u05d0\u05d9\u05df \u05e7\u05d1\u05d5\u05e6\u05d4 \u05d1\u05e9\u05d5\u05e8\u05d4, \u05ea\u05d3\u05d5\u05dc\u05d2"},
gG_(){return"\u05d4\u05db\u05ea\u05d1\u05d4"},
gJL(){return"\u05de\u05e7\u05e9\u05d9\u05d1\u05d9\u05dd\u2026 \u05d3\u05d1\u05e8\u05d5 \u05e2\u05db\u05e9\u05d9\u05d5"},
gBq(){return"\u05d4\u05db\u05ea\u05d1\u05d4 \u05dc\u05d0 \u05d6\u05de\u05d9\u05e0\u05d4 \u05d1\u05de\u05db\u05e9\u05d9\u05e8 \u05d4\u05d6\u05d4. \u05d4\u05e7\u05dc\u05d9\u05d3\u05d5 \u05d0\u05ea \u05d4\u05d4\u05e2\u05e8\u05d4"},
gOw(){return"\u05d1\u05e8\u05d5\u05db\u05d9\u05dd \u05d4\u05d1\u05d0\u05d9\u05dd \u05dc-Jita"},
gOr(){return"1 \xb7 \u05d4\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05e9\u05dc\u05db\u05dd"},
gOq(){return"\u05d1\u05d3\u05e7\u05d5 \u05e9\u05d0\u05dc\u05d4 \u05d0\u05db\u05df \u05d4\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05e9\u05dc\u05db\u05dd \u05d5\u05e9\u05d0\u05dc\u05d4 \u05e9\u05e2\u05d5\u05ea \u05d4\u05d0\u05d9\u05de\u05d5\u05df \u05e9\u05dc\u05d4\u05df. \u05d4\u05e7\u05d9\u05e9\u05d5 \u05e2\u05dc \u05e7\u05d1\u05d5\u05e6\u05d4 \u05db\u05d3\u05d9 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05dc\u05d5\u05d7 \u05d4\u05d0\u05d9\u05de\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc\u05d4."},
gOt(){return"2 \xb7 \u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9\u05dd"},
gOs(){return"\u05d9\u05d9\u05d1\u05d0\u05d5 \u05d0\u05ea \u05d4\u05e8\u05e9\u05d9\u05de\u05d4 \u05de-Excel: \u05d4\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05d5\u05dc\u05d5\u05d7 \u05d4\u05d0\u05d9\u05de\u05d5\u05e0\u05d9\u05dd \u05d9\u05d9\u05d5\u05d5\u05e6\u05e8\u05d5 \u05d0\u05d5\u05d8\u05d5\u05de\u05d8\u05d9\u05ea \u05d5\u05d4\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9\u05dd \u05d9\u05e9\u05d5\u05d1\u05e6\u05d5 \u05d1\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea."},
gOv(){return"3 \xb7 \u05d4\u05d5\u05e8\u05d9\u05dd"},
gOu(){return"\u05d4\u05d6\u05de\u05d9\u05e0\u05d5 \u05d4\u05d5\u05e8\u05d9\u05dd: \u05d4\u05dd \u05d9\u05e8\u05d0\u05d5 \u05d0\u05ea \u05d4\u05d7\u05d2\u05d5\u05e8\u05d4, \u05d4\u05de\u05e9\u05d9\u05de\u05d5\u05ea \u05d5\u05d4\u05de\u05e1\u05de\u05db\u05d9\u05dd \u05d5\u05d9\u05d5\u05db\u05dc\u05d5 \u05dc\u05d4\u05e2\u05dc\u05d5\u05ea \u05d0\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05e8\u05e4\u05d5\u05d0\u05d9\u05d9\u05dd."},
gza(){return"\u05d4\u05d1\u05d0"},
gBs(){return"\u05d4\u05ea\u05d7\u05dc\u05d4"},
gBg(){return"\u05d3\u05d9\u05dc\u05d5\u05d2"},
gAD(){return"\u05e6\u05e2\u05d3\u05d9\u05dd \u05e8\u05d0\u05e9\u05d5\u05e0\u05d9\u05dd"},
gzd(){return"\u05e2\u05d3\u05d9\u05d9\u05df \u05d0\u05d9\u05df \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea. \u05d0\u05ea \u05d4\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05d9\u05d5\u05e6\u05e8 \u05de\u05e0\u05d4\u05dc \u05d4\u05de\u05d5\u05e2\u05d3\u05d5\u05df, \u05d0\u05d5 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d9\u05d9\u05d1\u05d0 \u05d0\u05ea \u05e8\u05e9\u05d9\u05de\u05ea \u05d4\u05de\u05d5\u05e2\u05d3\u05d5\u05df \u05de-Excel."},
gzb(){return"\u05e2\u05d3\u05d9\u05d9\u05df \u05d0\u05d9\u05df \u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9\u05dd. \u05e4\u05ea\u05d7\u05d5 \u05e7\u05d1\u05d5\u05e6\u05d4 \u05d5\u05d9\u05d9\u05d1\u05d0\u05d5 \u05d0\u05ea \u05d4\u05e8\u05e9\u05d9\u05de\u05d4 \u05de-Excel."},
gG9(){return"\u05e9\u05dc\u05d7\u05d5 \u05d0\u05ea \u05d4\u05de\u05e1\u05de\u05da \u05d4\u05e8\u05d0\u05e9\u05d5\u05df (\u05dc\u05d5\u05d7 \u05d6\u05de\u05e0\u05d9\u05dd, \u05ea\u05e7\u05e0\u05d5\u05df \u05d0\u05d5 \u05d8\u05d5\u05e4\u05e1 \u05dc\u05de\u05d7\u05e0\u05d4) \u05d5\u05ea\u05d5\u05db\u05dc\u05d5 \u05dc\u05e8\u05d0\u05d5\u05ea \u05de\u05d9 \u05e4\u05ea\u05d7 \u05d0\u05d5\u05ea\u05d5."},
