gIn(){return"\u05d4\u05d6\u05de\u05d9\u05e0\u05d5 \u05d4\u05d5\u05e8\u05d9\u05dd \u05de\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d4\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9. \u05d4\u05dd \u05d9\u05d9\u05db\u05e0\u05e1\u05d5 \u05e2\u05dd \u05e7\u05d5\u05d3 \u05de\u05d4\u05d0\u05d9\u05de\u05d9\u05d9\u05dc."},
gwX(){return"\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9\u05dd"},
gEW(){return"\u05d7\u05d2\u05d5\u05e8\u05d4 \u05dc\u05d0 \u05e6\u05d5\u05d9\u05e0\u05d4"},
guI(){return"\u05d3\u05e8\u05d5\u05e9\u05d4 \u05d4\u05e9\u05dc\u05de\u05d4"},
gB_(){return"\u05e8\u05d2\u05d9\u05dc"},
gvB(){return"\u05e8\u05e0\u05d3\u05d5\u05e8\u05d9"},
gvA(){return"\u05d4\u05e9\u05dc\u05de\u05d4"},
gBr(){return"\u05e7\u05d1\u05d5\u05e6\u05ea \u05d4\u05de\u05d0\u05de\u05e0\u05d9\u05dd"},
gvI(){return"\u05dc\u05e6\u05d5\u05d5\u05ea \u05d1\u05dc\u05d1\u05d3. \u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9\u05dd \u05d5\u05d4\u05d5\u05e8\u05d9\u05dd \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4"},
gqV(){return"\u05d4\u05e8\u05e9\u05d0\u05d5\u05ea"},
gwf(){return"\u05de\u05d9 \u05e2\u05d5\u05d1\u05d3 \u05e2\u05dd \u05d0\u05d9\u05dc\u05d5 \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea"},
gp6(){return"\u05de\u05d0\u05de\u05df \u05e8\u05d0\u05e9\u05d9"},
gp5(){return"\u05e2\u05d5\u05d6\u05e8/\u05ea \u05de\u05d0\u05de\u05df"},
grR(){return"\u05de\u05e0\u05d4\u05dc \u05d4\u05de\u05d5\u05e2\u05d3\u05d5\u05df"},
gKz(){return"\u05e2\u05d3\u05d9\u05d9\u05df \u05d0\u05d9\u05df \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea"},
gtz(){return"\u05dc\u05e4\u05d9 \u05dc\u05d5\u05d7 \u05d4\u05d0\u05d9\u05de\u05d5\u05e0\u05d9\u05dd"},
gwg(){return"\u05e2\u05d3\u05d9\u05d9\u05df \u05dc\u05dc\u05d0 \u05d7\u05e9\u05d1\u05d5\u05df"},
gr2(){return"\u05d9\u05d5\u05de\u05df \u05e9\u05d9\u05e0\u05d5\u05d9\u05d9\u05dd"},
gtP(){return"\u05de\u05d9 \u05e9\u05d9\u05e0\u05d4 \u05d4\u05e8\u05e9\u05d0\u05d5\u05ea \u05d5\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd, \u05d5\u05de\u05ea\u05d9"},
gx_(){return"\u05e0\u05d5\u05e1\u05e3"},
gxb(){return"\u05e9\u05d5\u05e0\u05d4"},
gwZ(){return"\u05d4\u05d5\u05e1\u05e8"},
