gx9(){return"\u05d4\u05e8\u05e9\u05d0\u05d4"},
gx8(){return"\u05ea\u05e4\u05e7\u05d9\u05d3 \u05d1\u05d7\u05e9\u05d1\u05d5\u05df"},
gx7(){return"\u05d4\u05d6\u05de\u05e0\u05d4"},
gx6(){return"\u05e7\u05d1\u05d5\u05e6\u05d4"},
